const MODEL_METADATA_PREFIX: &str = "Model metadata for `";
const MODEL_METADATA_SUFFIX: &str =
    "` not found. Defaulting to fallback metadata; this can degrade performance and cause issues.";

/// Tracks which warnings have already been displayed so that repeated,
/// model-specific metadata warnings do not clutter the conversation history.
#[derive(Default)]
pub(super) struct WarningDisplayState {
    /// Model slugs for which a metadata warning has already been displayed.
    seen_model_metadata_slugs: HashSet<String>,
}

impl WarningDisplayState {
    /// Decide whether `message` should be added to the chat history.
    ///
    /// Model metadata warnings are deduplicated per-slug: the first warning for
    /// a given slug is displayed, and subsequent warnings for the same slug are
    /// suppressed. All other warnings are always displayed.
    pub(super) fn should_display(&mut self, message: &str) -> bool {
        match extract_model_metadata_slug(message) {
            Some(slug) => self.seen_model_metadata_slugs.insert(slug.to_string()),
            None => true,
        }
    }
}

/// Extract the model slug from a message that matches the exact model metadata
/// warning pattern, or `None` if the message does not match.
fn extract_model_metadata_slug(message: &str) -> Option<&str> {
    let rest = message.strip_prefix(MODEL_METADATA_PREFIX)?;
    rest.strip_suffix(MODEL_METADATA_SUFFIX)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn model_metadata_warning(slug: &str) -> String {
        format!(
            "Model metadata for `{slug}` not found. Defaulting to fallback metadata; this can degrade performance and cause issues."
        )
    }

    #[test]
    fn dedupes_model_metadata_warning_per_slug() {
        let mut state = WarningDisplayState::default();
        let warning = model_metadata_warning("unknown-model");

        assert!(state.should_display(&warning));
        assert!(!state.should_display(&warning));
        assert!(!state.should_display(&warning));
    }

    #[test]
    fn tracks_distinct_slugs_independently() {
        let mut state = WarningDisplayState::default();

        assert!(state.should_display(&model_metadata_warning("model-a")));
        assert!(state.should_display(&model_metadata_warning("model-b")));
        assert!(!state.should_display(&model_metadata_warning("model-a")));
        assert!(!state.should_display(&model_metadata_warning("model-b")));
    }

    #[test]
    fn always_displays_generic_warnings() {
        let mut state = WarningDisplayState::default();

        assert!(state.should_display("something went wrong"));
        assert!(state.should_display("something went wrong"));
        assert!(state.should_display("a different warning"));
    }
}
